ON CONFLICT (period_name, employee_id, work_date) DO UPDATE SET
  entry_time        = EXCLUDED.entry_time,
  exit_time         = EXCLUDED.exit_time,
  scheduled_start   = EXCLUDED.scheduled_start,
  grace_until       = EXCLUDED.grace_until,
  scheduled_end     = EXCLUDED.scheduled_end,
  late_minutes      = EXCLUDED.late_minutes,
  late_after_grace  = EXCLUDED.late_after_grace,
  early_leave_minutes = EXCLUDED.early_leave_minutes,
  discount_total_minutes = EXCLUDED.discount_total_minutes,
  payroll_ready     = EXCLUDED.payroll_ready,
  event_type_1      = EXCLUDED.event_type_1,
  pay_impact_1      = EXCLUDED.pay_impact_1,
  event_type_2      = EXCLUDED.event_type_2,
  pay_impact_2      = EXCLUDED.pay_impact_2,
  documentation     = EXCLUDED.documentation,
  notes             = EXCLUDED.notes,
  auto_notes        = EXCLUDED.auto_notes,
  initial_status    = EXCLUDED.initial_status,
  status_current    = EXCLUDED.status_current,
  updated_at        = NOW();

-- Refresh period summary counts
UPDATE periods p
SET
  green_count  = sub.green_count,
  yellow_count = sub.yellow_count,
  red_count    = sub.red_count
FROM (
  SELECT period_name,
    COUNT(*) FILTER (WHERE initial_status = 'GREEN')  AS green_count,
    COUNT(*) FILTER (WHERE initial_status = 'YELLOW') AS yellow_count,
    COUNT(*) FILTER (WHERE initial_status = 'RED')    AS red_count
  FROM payroll_entries
  GROUP BY period_name
) sub
WHERE p.period_name = sub.period_name;